//! Hero, karma and Mercenary Corps growth rules from the game's own tables.
//!
//! `data/growth.json` is generated by `scripts/gen-growth.mjs` from the XML
//! rule tables in the game's paks. Every EXP table is a running total: entry
//! N − 1 is the EXP at which level N starts. docs/game-rules.md records which
//! table each rule comes from.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::{Deserialize, Serialize};

const GROWTH_JSON: &str = include_str!("../data/growth.json");

/// The live-server profile whose limits the editor applies.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Region {
    /// Korea: breakthrough 5, hero level 70, grade 6, content version M11_3.
    Korea,
    /// America, Europe and Asia: breakthrough 4, hero level 60, grade 5,
    /// content version M11_2.
    Global,
}

/// The game is now an offline single-player release, and its in-game hero
/// level cap is 70 (observed 2026-10-26), which matches the Korean live
/// profile: breakthrough 5, grade 6 and active skills up to 10. A save does
/// not record its region. A save above these limits stays editable because
/// every setter keeps `max(limit, current)`.
pub const REGION: Region = Region::Korea;

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Growth {
    level_cap_base: i64,
    level_cap_step: i64,
    max_character_transcend: i64,
    max_karma_transcend: i64,
    hero_level_start_exp: Vec<i64>,
    karma_level_start_exp: HashMap<String, Vec<i64>>,
    karma_rarity: HashMap<String, String>,
    skills: HashMap<String, Vec<SkillLevel>>,
    advent_level_start_exp: Vec<i64>,
    advent_grades: Vec<AdventGrade>,
    main_quests: Vec<MainQuest>,
    quests: HashMap<String, Quest>,
    advent_level_rewards: Vec<Vec<(i64, i64)>>,
    heroes: Vec<Hero>,
    hero_items: HashMap<String, i64>,
    regions: Regions,
}

/// A hero the game hands out somewhere: the shop, a quest reward, or a
/// quest in which the hero joins the team.
#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Hero {
    pub id: i64,
    /// The hero item that redeems into this hero.
    pub item: i64,
    /// `shop`, `quest:<id>` or `joins:<id>`.
    pub sources: Vec<String>,
}

/// One quest from `QuestMainData`, with what completing it touches.
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Quest {
    pub category: String,
    /// The `CATEGORY` code saves use for this quest's category; none for a
    /// category no save shows, which the editor will not complete.
    pub save_category: Option<i64>,
    pub name_en: String,
    pub name_fr: String,
    /// Quests that must be complete before this one starts.
    pub requires: Vec<i64>,
    /// The game starts the quest by itself once `requires` is complete.
    pub auto_accept: bool,
    /// The corps level the quest needs, if any.
    pub adv_level: Option<i64>,
    pub first_step: Option<i64>,
    /// Lasting side effects: `TEAMSETTING_CHARACTER` (a hero joins),
    /// `TUTORIAL_DLG_COMPLITE` (a tutorial completes) and `DELETE_ITEM`.
    pub actions: Vec<(String, i64)>,
    pub gold: i64,
    pub adv_exp: i64,
    /// `(item CID, count)` pairs.
    pub items: Vec<(i64, i64)>,
}

/// One main-story quest, numbered the way the game shows it.
#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct MainQuest {
    pub id: i64,
    pub number: i64,
    pub name_en: String,
    pub name_fr: String,
}

#[derive(Debug, Deserialize)]
struct SkillLevel {
    ascend: i64,
    version: String,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct AdventGrade {
    pub grade: i64,
    pub name_en: String,
    pub name_fr: String,
    /// The quest that promotes to this grade; none for grade 1.
    pub promotion_quest: Option<i64>,
    pub character_ascend: i64,
    pub karma_ascend: i64,
    pub title_item: Option<i64>,
    /// What the promotion hands out: its title and, from Novice up, a mount.
    pub items: Vec<(i64, i64)>,
    /// The main quest the promotion exam waits for.
    pub requires_main_quest: Option<i64>,
}

#[derive(Debug, Deserialize)]
struct Regions {
    #[serde(rename = "KOR")]
    korea: RegionLimits,
    #[serde(rename = "GLOBAL")]
    global: RegionLimits,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RegionLimits {
    pub content_version: String,
    pub max_character_level: i64,
    pub max_character_ascend: i64,
    pub max_karma_level: i64,
    pub max_karma_ascend: i64,
    pub max_advent_level: i64,
    pub max_advent_grade: i64,
    pub max_advent_difficulty: i64,
}

/// The rarity whose karma table applies to a CID the game data does not list.
/// RARE has the lowest EXP per level, so an unknown karma gets the tightest cap.
const FALLBACK_KARMA_RARITY: &str = "RARE";

impl Growth {
    pub fn shared() -> &'static Self {
        static GROWTH: OnceLock<Growth> = OnceLock::new();
        GROWTH.get_or_init(|| {
            serde_json::from_str(GROWTH_JSON).expect("embedded growth tables are valid JSON")
        })
    }

    pub fn region(&self, region: Region) -> &RegionLimits {
        match region {
            Region::Korea => &self.regions.korea,
            Region::Global => &self.regions.global,
        }
    }

    pub fn max_character_transcend(&self) -> i64 {
        self.max_character_transcend
    }

    pub fn max_karma_transcend(&self) -> i64 {
        self.max_karma_transcend
    }

    /// The grade the region allows, for a saved grade. Grades outside the
    /// table clamp to the nearest one, so a future save cannot remove the caps.
    pub fn effective_grade(&self, grade: i64, region: Region) -> i64 {
        grade.clamp(1, self.region(region).max_advent_grade)
    }

    pub fn grade(&self, grade: i64) -> Option<&AdventGrade> {
        self.advent_grades.iter().find(|row| row.grade == grade)
    }

    /// The highest hero breakthrough a grade unlocks in a region.
    pub fn max_character_stage(&self, grade: i64, region: Region) -> i64 {
        let grade = self.effective_grade(grade, region);
        self.grade(grade)
            .map_or(0, |row| row.character_ascend)
            .min(self.region(region).max_character_ascend)
    }

    /// The highest karma breakthrough a grade unlocks in a region.
    pub fn max_karma_stage(&self, grade: i64, region: Region) -> i64 {
        let grade = self.effective_grade(grade, region);
        self.grade(grade)
            .map_or(0, |row| row.karma_ascend)
            .min(self.region(region).max_karma_ascend)
    }

    /// The promotion quests the region's grades use, in order.
    pub fn promotion_quests(&self, region: Region) -> Vec<i64> {
        let max = self.region(region).max_advent_grade;
        self.advent_grades
            .iter()
            .filter(|row| row.grade <= max)
            .filter_map(|row| row.promotion_quest)
            .collect()
    }

    /// The main story in the game's own numbering.
    pub fn main_quests(&self) -> &[MainQuest] {
        &self.main_quests
    }

    pub fn quest(&self, id: i64) -> Option<&Quest> {
        self.quests.get(&id.to_string())
    }

    /// Every quest, keyed by ID.
    pub fn quests(&self) -> impl Iterator<Item = (i64, &Quest)> {
        self.quests
            .iter()
            .filter_map(|(id, quest)| Some((id.parse().ok()?, quest)))
    }

    /// The heroes the game hands out, in ID order.
    pub fn heroes(&self) -> &[Hero] {
        &self.heroes
    }

    pub fn hero(&self, id: i64) -> Option<&Hero> {
        self.heroes.iter().find(|hero| hero.id == id)
    }

    /// The hero a hero item redeems into.
    pub fn hero_for_item(&self, item: i64) -> Option<i64> {
        self.hero_items.get(&item.to_string()).copied()
    }

    /// What reaching a corps level hands out.
    pub fn advent_level_reward(&self, level: i64) -> &[(i64, i64)] {
        usize::try_from(level - 1)
            .ok()
            .and_then(|index| self.advent_level_rewards.get(index))
            .map_or(&[], Vec::as_slice)
    }

    pub fn main_quest(&self, id: i64) -> Option<&MainQuest> {
        self.main_quests.iter().find(|quest| quest.id == id)
    }

    /// The level cap at a breakthrough stage. No table holds this; the
    /// generator checks that 20 + 10 × stage meets every region's live maximum.
    pub fn level_cap(&self, stage: i64) -> i64 {
        self.level_cap_base + self.level_cap_step * stage
    }

    /// The lowest stage whose level cap admits `level`.
    pub fn stage_for_level(&self, level: i64) -> i64 {
        ((level - self.level_cap_base).max(0) + self.level_cap_step - 1) / self.level_cap_step
    }

    /// The highest level a skill type reaches at a breakthrough stage in a
    /// region, or `None` for a type the game data does not list.
    pub fn skill_cap(&self, type_value: i64, stage: i64, region: Region) -> Option<i64> {
        let live = version_key(&self.region(region).content_version);
        let levels = self.skills.get(&type_value.to_string())?;
        Some(
            levels
                .iter()
                .take_while(|level| level.ascend <= stage && version_key(&level.version) <= live)
                .count() as i64,
        )
    }

    pub fn hero_exp(&self) -> &[i64] {
        &self.hero_level_start_exp
    }

    pub fn advent_exp(&self) -> &[i64] {
        &self.advent_level_start_exp
    }

    /// The level table for a karma, by the rarity the game data gives its CID.
    pub fn karma_exp(&self, cid: i64) -> &[i64] {
        self.karma_rarity
            .get(&cid.to_string())
            .and_then(|rarity| self.karma_level_start_exp.get(rarity))
            .or_else(|| self.karma_level_start_exp.get(FALLBACK_KARMA_RARITY))
            .map_or(&[], Vec::as_slice)
    }
}

/// The EXP at which `level` starts, if the table reaches it.
pub fn start_exp(table: &[i64], level: i64) -> Option<i64> {
    usize::try_from(level - 1)
        .ok()
        .and_then(|index| table.get(index))
        .copied()
}

/// The EXP a row at `level` may hold when `cap` is its level cap. EXP past the
/// cap is refunded in game, so a capped row sits at the level's start.
pub fn exp_range(table: &[i64], level: i64, cap: i64) -> Option<(i64, i64)> {
    let low = start_exp(table, level)?;
    let high = if level >= cap {
        low
    } else {
        start_exp(table, level + 1).map_or(low, |next| next - 1)
    };
    Some((low, high))
}

/// The level a running-total EXP value reaches.
pub fn level_for_exp(table: &[i64], exp: i64) -> i64 {
    table
        .iter()
        .take_while(|start| **start <= exp)
        .count()
        .max(1) as i64
}

/// Content versions look like `M11_2`; compare them numerically.
fn version_key(version: &str) -> (u32, u32) {
    let digits = version.trim_start_matches('M');
    let (major, minor) = digits.split_once('_').unwrap_or((digits, "0"));
    (
        major.parse().unwrap_or(u32::MAX),
        minor.parse().unwrap_or(u32::MAX),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    // These rows come from the game's tables. A regenerated growth.json that
    // changes one must fail here, so the change is looked at on purpose.

    #[test]
    fn hero_levels_are_a_running_total() {
        let growth = Growth::shared();
        let table = growth.hero_exp();
        assert_eq!(table.len(), 100);
        assert_eq!(&table[..5], &[0, 150, 400, 900, 1_600]);
        assert_eq!(start_exp(table, 20), Some(76_900));
        assert_eq!(start_exp(table, 60), Some(1_896_700));
        assert_eq!(start_exp(table, 70), Some(2_990_400));
        // The game-written save's heroes: 170 at level 2, 595 at 3, 2,465 at 5.
        assert_eq!(level_for_exp(table, 170), 2);
        assert_eq!(level_for_exp(table, 595), 3);
        assert_eq!(level_for_exp(table, 2_465), 5);
        assert_eq!(exp_range(table, 5, 20), Some((1_600, 2_599)));
        assert_eq!(exp_range(table, 20, 20), Some((76_900, 76_900)));
    }

    #[test]
    fn regions_and_grades_match_the_game() {
        let growth = Growth::shared();
        let korea = growth.region(Region::Korea);
        let global = growth.region(Region::Global);
        assert_eq!(
            (
                korea.max_character_level,
                korea.max_character_ascend,
                korea.max_advent_grade
            ),
            (70, 5, 6)
        );
        assert_eq!(
            (
                global.max_character_level,
                global.max_character_ascend,
                global.max_advent_grade
            ),
            (60, 4, 5)
        );
        assert_eq!(korea.max_advent_level, 50);
        assert_eq!(global.max_advent_level, 50);
        assert_eq!(growth.max_character_transcend(), 6);
        assert_eq!(growth.max_karma_transcend(), 6);

        let names: Vec<&str> = growth
            .advent_grades
            .iter()
            .map(|row| row.name_en.as_str())
            .collect();
        assert_eq!(
            names,
            [
                "Apprentice",
                "Novice",
                "Intermediate",
                "Advanced",
                "Elite",
                "Veteran"
            ]
        );
        assert_eq!(
            growth.promotion_quests(Region::Korea),
            [40_001, 40_011, 40_021, 40_031, 40_041]
        );
        assert_eq!(
            growth.promotion_quests(Region::Global),
            [40_001, 40_011, 40_021, 40_031]
        );
        assert_eq!(growth.max_character_stage(1, Region::Global), 0);
        assert_eq!(growth.max_character_stage(3, Region::Global), 2);
        assert_eq!(growth.max_character_stage(6, Region::Global), 4);
        assert_eq!(growth.max_character_stage(6, Region::Korea), 5);
        assert_eq!(growth.max_character_stage(0, Region::Korea), 0);
    }

    #[test]
    fn level_caps_follow_the_stage() {
        let growth = Growth::shared();
        let caps: Vec<i64> = (0..=5).map(|stage| growth.level_cap(stage)).collect();
        assert_eq!(caps, [20, 30, 40, 50, 60, 70]);
        assert_eq!(growth.stage_for_level(1), 0);
        assert_eq!(growth.stage_for_level(20), 0);
        assert_eq!(growth.stage_for_level(21), 1);
        assert_eq!(growth.stage_for_level(35), 2);
        assert_eq!(growth.stage_for_level(70), 5);
    }

    #[test]
    fn skill_caps_follow_the_stage_and_content_version() {
        let growth = Growth::shared();
        let caps = |type_value, region| -> Vec<i64> {
            (0..=5)
                .map(|stage| growth.skill_cap(type_value, stage, region).unwrap())
                .collect()
        };
        // Active levels 8–10 arrived in M11_3, which only Korea runs.
        assert_eq!(caps(1, Region::Korea), [3, 5, 7, 9, 10, 10]);
        assert_eq!(caps(4, Region::Global), [3, 5, 7, 7, 7, 7]);
        assert_eq!(caps(5, Region::Korea), [3, 5, 7, 7, 7, 7]);
        assert_eq!(caps(7, Region::Global), [3, 5, 7, 7, 7, 7]);
        assert_eq!(caps(801, Region::Global), [1; 6]);
        assert_eq!(caps(8, Region::Global), [1; 6]);
        assert_eq!(growth.skill_cap(9, 0, Region::Global), None);
    }

    #[test]
    fn karma_levels_follow_rarity() {
        let growth = Growth::shared();
        // 1710501 is LEGENDARY. Its table differs from the hero table at
        // level 2 but meets it at level 70.
        let legendary = growth.karma_exp(1_710_501);
        assert_eq!(&legendary[..3], &[0, 200, 400]);
        assert_eq!(start_exp(legendary, 70), Some(2_990_400));
        // An unknown CID gets the RARE table, the tightest one.
        assert_eq!(start_exp(growth.karma_exp(1), 20), Some(50_200));
        assert_eq!(growth.karma_exp(1).len(), 80);
    }

    #[test]
    fn promotions_wait_for_the_main_story() {
        let growth = Growth::shared();
        assert_eq!(growth.main_quests().len(), 80);
        let story = |grade| {
            let id = growth.grade(grade).unwrap().requires_main_quest.unwrap();
            let quest = growth.main_quest(id).unwrap();
            (quest.id, quest.number)
        };
        // Quest IDs skip between chapters: quest 21 is 10031.
        assert_eq!(story(2), (10_020, 20));
        assert_eq!(story(3), (10_050, 40));
        assert_eq!(story(4), (10_060, 50));
        assert_eq!(story(5), (10_070, 60));
        assert_eq!(story(6), (10_090, 80));
        assert_eq!(growth.main_quest(10_031).unwrap().number, 21);
        assert_eq!(growth.main_quest(10_013).unwrap().name_en, "The Sixth Hero");
    }

    #[test]
    fn quests_list_their_rewards() {
        let growth = Growth::shared();
        let first = growth.quest(10_001).unwrap();
        assert_eq!((first.gold, first.adv_exp, first.items.len()), (0, 0, 0));
        let captain = growth.quest(10_009).unwrap();
        assert_eq!((captain.gold, captain.adv_exp), (2_500, 400));
        assert_eq!(
            captain.items,
            [
                (1_410_002, 20),
                (1_410_202, 10),
                (1_320_016, 1),
                (1_110_601, 1),
                (1_000_500, 1)
            ]
        );
    }

    #[test]
    fn quests_know_what_completing_them_touches() {
        let growth = Growth::shared();
        let second = growth.quest(10_002).unwrap();
        assert_eq!(second.save_category, Some(1));
        assert_eq!(second.requires, [10_001]);
        assert!(second.auto_accept);
        assert_eq!(second.first_step, Some(1));
        assert!(
            second
                .actions
                .contains(&("TEAMSETTING_CHARACTER".to_string(), 10_003))
        );
        let exam = growth.quest(40_011).unwrap();
        assert_eq!(exam.save_category, Some(7));
        assert_eq!(exam.requires, [40_001, 10_050]);
        assert_eq!(
            growth.grade(2).unwrap().items,
            [(2_104_100, 1), (1_320_012, 1)]
        );
        assert_eq!(growth.advent_level_reward(2), [(1_410_002, 10)]);
        assert_eq!(growth.advent_level_reward(81), []);
    }

    #[test]
    fn heroes_come_from_the_shop_quests_and_story() {
        let growth = Growth::shared();
        let ids: Vec<i64> = growth.heroes().iter().map(|hero| hero.id).collect();
        assert_eq!(ids.len(), 19);
        assert!(ids.contains(&10_004), "Reina, from the shop");
        assert!(!ids.contains(&10_009), "Ropie: nothing hands her out");
        assert!(!ids.contains(&10_002), "Lute is always in the party");
        assert_eq!(growth.hero(10_006).unwrap().sources, ["joins:10005"]);
        assert_eq!(growth.hero_for_item(1_110_601), Some(10_007), "Johnny");
        assert_eq!(growth.hero_for_item(1_110_301), Some(10_004), "Reina");
    }

    #[test]
    fn corps_levels_are_a_running_total() {
        let table = Growth::shared().advent_exp();
        assert_eq!(&table[..4], &[0, 800, 1_650, 2_550]);
        assert_eq!(start_exp(table, 50), Some(512_500));
        // The played save is corps level 3 with 1,800 EXP.
        assert_eq!(level_for_exp(table, 1_800), 3);
    }
}
